import{_ as s,C as n,c as r,o as i,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Pay and receipt","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/selling/pay-and-receipt.md","filePath":"master/sales/point-of-sale/selling/pay-and-receipt.md","lastUpdated":1793074831000}'),h={name:"master/sales/point-of-sale/selling/pay-and-receipt.md"};function l(c,e,d,p,m,u){const a=n("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="pay-and-receipt" tabindex="-1">Pay and receipt <a class="header-anchor" href="#pay-and-receipt" aria-label="Permalink to &quot;Pay and receipt&quot;">​</a></h1><p>Payment closes the sale. You choose how the customer pays, enter the amount, and click <strong>Validate</strong>. The terminal then shows the receipt, ready to print.</p><blockquote><p><strong>In simple words:</strong> Pick the payment method, type what the customer hands over, click Validate, and give the receipt.</p></blockquote><h2 id="open-the-payment-screen" tabindex="-1">Open the payment screen <a class="header-anchor" href="#open-the-payment-screen" aria-label="Permalink to &quot;Open the payment screen&quot;">​</a></h2><p>Click <strong>Payment</strong> at the bottom right of the order panel. The button is active only when the order has lines.</p>',5)),o(a,{src:"/images1/pos/payment_screen_methods.png",alt:"Payment screen for the 6,597 order with the Cash payment method, customer button and Invoice option"}),e[1]||(e[1]=t('<p>The screen shows:</p><ul><li>The big <strong>total</strong> to pay at the top left.</li><li>The list of <strong>payment methods</strong> on the right, such as <strong>Cash</strong>.</li><li>The customer button and the <strong>Invoice</strong> checkbox.</li><li>The number pad with <strong>+10</strong>, <strong>+20</strong> and <strong>+50</strong>.</li><li><strong>Back</strong> and <strong>Validate</strong> buttons.</li></ul><p>Payment methods come from your register. See <a href="./../payments-setup/payment-methods.html">Payment methods</a>.</p><h2 id="take-a-cash-payment" tabindex="-1">Take a cash payment <a class="header-anchor" href="#take-a-cash-payment" aria-label="Permalink to &quot;Take a cash payment&quot;">​</a></h2><ol><li>Click <strong>Cash</strong>. A payment line appears with the amount due.</li><li>Type the amount the customer gives, for example 7000. Use <strong>+10</strong>, <strong>+20</strong> and <strong>+50</strong> to add to the amount fast.</li><li>Check the <strong>Change</strong> panel. It shows what you give back.</li></ol>',5)),o(a,{src:"/images1/pos/payment_cash_change.png",alt:"Payment screen with Cash 7,000 entered for a 6,597 order and a Change amount of 403"}),e[2]||(e[2]=t('<p><strong>Example:</strong> Sofia Rossi&#39;s order is 6,597. She hands over 7,000. The screen shows <strong>Change</strong> 403.</p><p>Click the red <strong>X</strong> on a payment line to remove it.</p><h3 id="pay-with-more-than-one-method" tabindex="-1">Pay with more than one method <a class="header-anchor" href="#pay-with-more-than-one-method" aria-label="Permalink to &quot;Pay with more than one method&quot;">​</a></h3><p>Add a second method and enter its amount. The first line shows what is still due. Together the payments must cover the total.</p><h3 id="rules-the-screen-applies" tabindex="-1">Rules the screen applies <a class="header-anchor" href="#rules-the-screen-applies" aria-label="Permalink to &quot;Rules the screen applies&quot;">​</a></h3><ul><li>You cannot validate until a payment method covers the total. The message is &quot;Payment method required&quot;.</li><li>Without a cash method, a payment cannot be higher than the amount due.</li><li>If <strong>Customer Required</strong> is on, or a method needs a customer, pick one first. See <a href="./order-notes-and-customers.html">Notes and customers</a>.</li></ul><h2 id="invoice-option" tabindex="-1">Invoice option <a class="header-anchor" href="#invoice-option" aria-label="Permalink to &quot;Invoice option&quot;">​</a></h2><p>Tick <strong>Invoice</strong> if the customer wants a customer invoice. You need a customer on the order. See <a href="./invoice-a-pos-order.html">Invoice a POS order</a>.</p><h2 id="validate" tabindex="-1">Validate <a class="header-anchor" href="#validate" aria-label="Permalink to &quot;Validate&quot;">​</a></h2><p>Click <strong>Validate</strong>. The order becomes <strong>Paid</strong> and the receipt screen opens.</p><h2 id="the-receipt-screen" tabindex="-1">The receipt screen <a class="header-anchor" href="#the-receipt-screen" aria-label="Permalink to &quot;The receipt screen&quot;">​</a></h2><p>The receipt shows the company, <strong>Served by</strong>, the tracking number, the customer, each line, the <strong>Untaxed amount</strong>, the <strong>TOTAL</strong>, each payment, the <strong>Change</strong> and the order number with date.</p>',12)),o(a,{src:"/images1/pos/receipt_screen.png",alt:"Receipt screen for the order with lines, TOTAL 6,597, Cash 7,000, Change 403 and the Print and New order buttons"}),e[3]||(e[3]=t('<ul><li><strong>Print:</strong> Prints the receipt.</li><li><strong>New order:</strong> Starts a fresh order.</li></ul><p>The receipt number has three parts: register, session and order. For TechNest the receipt is <strong>00004-009-0001</strong>. The order number is <strong>TNE/00001</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Your register can print receipts by itself after payment. The setting is in the <strong>Bills &amp; Receipts</strong> tab of the register.</p></div><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Back:</strong> Returns to the order without paying.</li><li><strong>Validate:</strong> Settles the order. Status <strong>Paid</strong>.</li><li>After the session closes, the order becomes <strong>Posted</strong>.</li><li>If you invoice it, the status becomes <strong>Invoiced</strong>.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You cannot change a paid order. To return products, use a refund. See <a href="./refunds.html">Refunds</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./take-an-order.html">Take an order</a></li><li><a href="./refunds.html">Refunds</a></li><li><a href="./../sessions/close-session.html">Close a session</a></li></ul>',8))])}const y=s(h,[["render",l]]);export{_ as __pageData,y as default};
